text:
{
  "table": {
    "name": "yearmonth",
    "purpose": "Monthly per-customer consumption summary: one row per customer per year-month, aggregating that customer's activity (presumably from the gas-station transaction data) into a single Consumption figure. The logical primary key is the pair (CustomerID, Date)."
  },
  "columns": {
    "Consumption": {
      "role": "numeric",
      "name": "Monthly consumption total per customer",
      "description": "Aggregated consumption figure for one customer in one year-month. Strongly right-skewed (median ~1,766, mean ~8,911, range -582,092.86 to 2,052,187.11); the negative values indicate refunds, credits or corrections rather than physical consumption. The unit cannot be determined from the available evidence: the magnitudes fit equally well a fuel volume (e.g. litres) or a monetary amount (e.g. euros spent at the gas stations), so the unit remains unresolved. It is also not directly verifiable whether the value is a plain monthly sum or some normalized/averaged figure, though a monthly total is the natural reading of the values and column name.",
      "status": "tentative"
    },
    "CustomerID": {
      "role": "foreign_key",
      "name": "Customer ID",
      "description": "Foreign key to customers.CustomerID (many-to-one) identifying the customer the row belongs to. 30,566 distinct customers (IDs 5-52,353), each appearing in up to ~21 rows (one per month). Together with Date it forms the row's identity: one consumption value per customer per month.",
      "status": "resolved"
    },
    "Date": {
      "role": "date",
      "name": "Year-month (YYYYMM)",
      "description": "Year-month period code in YYYYMM format stored as text (e.g. 201305 = May 2013); despite the column name there is no day component. 21 distinct values spanning 201112 (Dec 2011) to 201311 (Nov 2013), each month holding ~25,000-25,500 rows, i.e. most customers have one row per month. Second component of the customer+month identity of each row.",
      "status": "resolved"
    }
  }
}
